<?php
declare(strict_types=1);
session_start();
require __DIR__ . '/db.php';
if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32));
function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES|ENT_SUBSTITUTE, 'UTF-8'); }
function home(): never { header('Location: index.php'); exit; }
$estados = ['Preparando','Despacho']; $error=''; $form=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!hash_equals($_SESSION['csrf'], (string)($_POST['csrf']??''))) { http_response_code(403); exit('Solicitud no válida. Recarga la página.'); }
    $action=(string)($_POST['action']??'');
    if ($action==='delete') { $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); if($id){$s=$pdo->prepare('DELETE FROM pedidos WHERE id=?');$s->execute([$id]);} home(); }
    if ($action==='status') { $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$estado=(string)($_POST['estado']??'');if($id&&in_array($estado,$estados,true)){$s=$pdo->prepare('UPDATE pedidos SET estado=? WHERE id=?');$s->execute([$estado,$id]);}home(); }
    if ($action==='save') {
        $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:null; $direccion=trim((string)($_POST['direccion']??''));$estado=(string)($_POST['estado']??'Preparando');
        $sencilla=filter_var($_POST['sencilla']??null,FILTER_VALIDATE_INT);$doble=filter_var($_POST['doble']??null,FILTER_VALIDATE_INT);$mixta=filter_var($_POST['mixta']??null,FILTER_VALIDATE_INT);
        $form=compact('id','direccion','estado','sencilla','doble','mixta');
        if($direccion==='')$error='La dirección de entrega es obligatoria.';
        elseif(mb_strlen($direccion)>255)$error='La dirección admite máximo 255 caracteres.';
        elseif(!in_array($estado,$estados,true))$error='Estado no válido.';
        elseif($sencilla===false||$doble===false||$mixta===false||$sencilla===null||$doble===null||$mixta===null||$sencilla<0||$doble<0||$mixta<0||$sencilla>10000||$doble>10000||$mixta>10000)$error='Las cantidades deben ser enteros entre 0 y 10.000.';
        elseif($sencilla+$doble+$mixta<1)$error='El pedido debe incluir al menos una hamburguesa.';
        else { if($id){$s=$pdo->prepare('UPDATE pedidos SET direccion=?, sencilla=?, doble=?, mixta=?, estado=? WHERE id=?');$s->execute([$direccion,$sencilla,$doble,$mixta,$estado,$id]);}else{$s=$pdo->prepare('INSERT INTO pedidos(direccion,sencilla,doble,mixta,estado) VALUES(?,?,?,?,?)');$s->execute([$direccion,$sencilla,$doble,$mixta,$estado]);}home(); }
    }
}
if(isset($_GET['editar'])&&!$form){$id=filter_input(INPUT_GET,'editar',FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT id,direccion,sencilla,doble,mixta,estado FROM pedidos WHERE id=?');$s->execute([$id]);$form=$s->fetch()?:null;}}
$q=trim((string)($_GET['q']??''));$filtro=(string)($_GET['estado']??'');$sql='SELECT * FROM pedidos WHERE 1=1';$params=[];
if($q!==''){$sql.=' AND direccion LIKE ?';$params[]='%'.$q.'%';}if(in_array($filtro,$estados,true)){$sql.=' AND estado=?';$params[]=$filtro;}$sql.=' ORDER BY creado_en DESC,id DESC';$s=$pdo->prepare($sql);$s->execute($params);$pedidos=$s->fetchAll();
$total=(int)$pdo->query('SELECT COUNT(*) FROM pedidos')->fetchColumn();$preparando=(int)$pdo->query("SELECT COUNT(*) FROM pedidos WHERE estado='Preparando'")->fetchColumn();$despacho=(int)$pdo->query("SELECT COUNT(*) FROM pedidos WHERE estado='Despacho'")->fetchColumn();$unidades=(int)$pdo->query('SELECT COALESCE(SUM(sencilla+doble+mixta),0) FROM pedidos')->fetchColumn();
$v=static fn(string $k,mixed $d='')=>$form[$k]??$d;$editing=is_array($form)&&!empty($form['id']);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos de hamburguesería</title>
<style>
:root{--red:#c73b2d;--dark:#98281f;--ink:#292522;--muted:#766e68;--line:#e9e0d8;--bg:#fff8f1}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}header{background:linear-gradient(120deg,#8f211b,#d94a32);color:white;padding:25px 20px}.wrap{max-width:1200px;margin:auto;padding:0 18px}.brand{display:flex;align-items:center;gap:14px}.logo{font-size:38px}h1{font-size:27px;margin:0}header p{margin:3px 0 0;color:#ffe9df}main{padding:25px 0 50px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:20px}.stat,.panel{background:white;border:1px solid var(--line);border-radius:15px;box-shadow:0 4px 18px #5a2a0b0a}.stat{padding:16px}.stat span{color:var(--muted);font-size:13px}.stat strong{display:block;font-size:27px;margin-top:3px}.layout{display:grid;grid-template-columns:350px minmax(0,1fr);gap:20px;align-items:start}.panel{padding:20px}.panel h2{font-size:19px;margin:0 0 15px}label{display:block;font-weight:650;font-size:13px;margin:13px 0 6px}input,select{width:100%;border:1px solid #d8cec5;border-radius:9px;padding:10px 11px;font:inherit;background:white;color:var(--ink)}input:focus,select:focus{outline:2px solid #f0b1a8;border-color:var(--red)}.qty{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.qty label{font-size:12px}.qty input{padding:9px 6px}button,.btn{border:0;border-radius:9px;padding:10px 13px;font:inherit;font-weight:700;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:6px}.primary{background:var(--red);color:white;width:100%;margin-top:17px}.primary:hover{background:var(--dark)}.secondary{background:#f4ece5;color:#493b32}.danger{background:#fff0ed;color:#a62c22}.small{padding:7px 9px;font-size:12px}.error{background:#fff0ed;border:1px solid #efc1ba;color:#8b2119;border-radius:9px;padding:10px;margin-bottom:12px}.filters{display:flex;gap:8px;margin-bottom:14px}.filters input{flex:1;min-width:100px}.filters select{width:160px}.filters button{background:#302a26;color:white}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #eee6df;vertical-align:top}th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);background:#fffaf6}td{font-size:14px}.id{font-weight:800;color:var(--red)}.address{font-weight:700;max-width:230px;overflow-wrap:anywhere}.muted{color:var(--muted);font-size:12px}.pills{display:flex;flex-wrap:wrap;gap:5px}.pill{display:inline-block;border-radius:20px;padding:4px 8px;font-size:12px;font-weight:750;background:#f6eee7;white-space:nowrap}.prep{background:#fff0cc;color:#81500b}.desp{background:#dff5e8;color:#17633b}.actions{display:flex;gap:6px;flex-wrap:wrap}.status-form{display:flex;gap:5px;align-items:center;margin-top:8px}.status-form select{font-size:12px;padding:6px;min-width:105px}.empty{text-align:center;padding:35px 15px;color:var(--muted)}@media(max-width:950px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){h1{font-size:22px}.panel{padding:14px}.filters{flex-wrap:wrap}.filters input,.filters select{width:100%;flex:auto}.stats{gap:8px}.stat{padding:12px}.stat strong{font-size:23px}}
</style></head><body>
<header><div class="wrap brand"><div class="logo">🍔</div><div><h1>Pedidos de hamburguesería</h1><p>Administra direcciones, cantidades y estado de cada pedido</p></div></div></header><main class="wrap">
<section class="stats"><div class="stat"><span>Pedidos registrados</span><strong><?= $total ?></strong></div><div class="stat"><span>Preparando</span><strong><?= $preparando ?></strong></div><div class="stat"><span>En despacho</span><strong><?= $despacho ?></strong></div><div class="stat"><span>Hamburguesas pedidas</span><strong><?= $unidades ?></strong></div></section>
<div class="layout"><section class="panel"><h2><?= $editing?'✏️ Editar pedido #'.(int)$v('id'):'➕ Registrar pedido' ?></h2><?php if($error!==''): ?><div class="error"><?= h($error) ?></div><?php endif; ?>
<form method="post" action="index.php"><input type="hidden" name="csrf" value="<?= h($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= h($v('id')) ?>"><label for="direccion">Dirección de entrega *</label><input id="direccion" name="direccion" maxlength="255" required value="<?= h($v('direccion')) ?>" placeholder="Calle, número, barrio..."><label>Cantidad por tipo de hamburguesa *</label><div class="qty"><div><label for="sencilla">Sencilla</label><input id="sencilla" type="number" name="sencilla" min="0" max="10000" step="1" required value="<?= h($v('sencilla',0)) ?>"></div><div><label for="doble">Doble</label><input id="doble" type="number" name="doble" min="0" max="10000" step="1" required value="<?= h($v('doble',0)) ?>"></div><div><label for="mixta">Mixta</label><input id="mixta" type="number" name="mixta" min="0" max="10000" step="1" required value="<?= h($v('mixta',0)) ?>"></div></div><label for="estado">Estado del pedido</label><select id="estado" name="estado"><?php foreach($estados as $e): ?><option value="<?= h($e) ?>" <?= $v('estado','Preparando')===$e?'selected':'' ?>><?= h($e) ?></option><?php endforeach; ?></select><button class="primary" type="submit"><?= $editing?'Guardar cambios':'Crear pedido' ?></button><?php if($editing): ?><a class="btn secondary" style="width:100%;margin-top:8px" href="index.php">Cancelar edición</a><?php endif; ?></form><p class="muted">La dirección es obligatoria y el pedido debe incluir al menos una hamburguesa.</p></section>
<section class="panel"><h2>📋 Pedidos registrados</h2><form class="filters" method="get" action="index.php"><input name="q" value="<?= h($q) ?>" placeholder="Buscar por dirección..."><select name="estado"><option value="">Todos los estados</option><?php foreach($estados as $e): ?><option value="<?= h($e) ?>" <?= $filtro===$e?'selected':'' ?>><?= h($e) ?></option><?php endforeach; ?></select><button type="submit">Buscar</button><?php if($q!==''||$filtro!==''): ?><a class="btn secondary" href="index.php">Limpiar</a><?php endif; ?></form><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Dirección</th><th>Cantidades</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
<?php if(!$pedidos): ?><tr><td colspan="5" class="empty">No hay pedidos que coincidan con la búsqueda.</td></tr><?php else: foreach($pedidos as $p): ?><tr><td><span class="id">#<?= (int)$p['id'] ?></span><div class="muted"><?= h(date('d/m/Y H:i',strtotime($p['creado_en']))) ?></div></td><td><div class="address"><?= h($p['direccion']) ?></div></td><td><div class="pills"><span class="pill">Sencilla: <?= (int)$p['sencilla'] ?></span><span class="pill">Doble: <?= (int)$p['doble'] ?></span><span class="pill">Mixta: <?= (int)$p['mixta'] ?></span></div><div class="muted" style="margin-top:5px">Total: <?= (int)$p['sencilla']+(int)$p['doble']+(int)$p['mixta'] ?> unidad(es)</div></td><td><span class="pill <?= $p['estado']==='Preparando'?'prep':'desp' ?>"><?= h($p['estado']) ?></span><form class="status-form" method="post" action="index.php"><input type="hidden" name="csrf" value="<?= h($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><select name="estado" aria-label="Estado del pedido #<?= (int)$p['id'] ?>"><?php foreach($estados as $e): ?><option value="<?= h($e) ?>" <?= $p['estado']===$e?'selected':'' ?>><?= h($e) ?></option><?php endforeach; ?></select><button class="secondary small" type="submit">Actualizar</button></form></td><td><div class="actions"><a class="btn secondary small" href="index.php?editar=<?= (int)$p['id'] ?>">Editar</a><form method="post" action="index.php" onsubmit="return confirm('¿Eliminar el pedido #<?= (int)$p['id'] ?>?');"><input type="hidden" name="csrf" value="<?= h($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="danger small" type="submit">Eliminar</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></section></div></main></body></html>
